function validate([nums]) {
  if (nums.length < 1 || nums.length > 100) return 'nums needs 1 to 100 numbers.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 99)) return 'Each number is an integer from 1 to 99.';
  return null;
}

