function canAliceWin(nums) {
  // Play both options and see whether either one beats Bob.
  for (const digits of [1, 2]) {
    let alice = 0;
    let bob = 0;
    for (const num of nums) {
      if (String(num).length === digits) alice += num;
      else bob += num;
    }
    if (alice > bob) return true;
  }
  return false;
}

