function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const mode = rand();
  let nums = [];
  if (mode < 0.4) {
    const n = large ? 100 : pick(1, 8);
    for (let i = 0; i < n; i++) nums.push(rand() < 0.5 ? pick(1, 9) : pick(10, 99));
    return [nums];
  }
  // Otherwise the two groups get equal sums (a tie), and sometimes one value is nudged so a group wins by 1.
  const singles = [];
  const m = large ? pick(80, 90) : pick(2, 6);
  for (let i = 0; i < m; i++) singles.push(pick(1, 9));
  let total = singles.reduce((a, b) => a + b, 0);
  while (total < 10) { const v = pick(1, 9); singles.push(v); total += v; }
  const k = Math.max(1, Math.min(large ? 100 - singles.length : pick(1, 3), Math.floor(total / 10)));
  const doubles = new Array(k).fill(10);
  let rest = total - 10 * k;
  while (rest > 0) {
    const i = pick(0, k - 1);
    const add = Math.min(rest, 99 - doubles[i], pick(1, 30));
    doubles[i] += add;
    rest -= add;
  }
  if (mode > 0.75) {
    const i = pick(0, singles.length - 1);
    singles[i] += singles[i] === 9 || (singles[i] > 1 && rand() < 0.5) ? -1 : 1;
  }
  nums = singles.concat(doubles);
  for (let i = nums.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  return [nums];
}
